const {test,expect}=require('@playwright/test');
const fs=require('node:fs'),path=require('node:path'),ts=require('../estimating-app/node_modules/typescript');
const {PDFDocument,StandardFonts,rgb,degrees,PDFName}=require('../estimating-app/node_modules/pdf-lib');
const cache={};function load(name){if(cache[name])return cache[name];const m={exports:{}};Function('exports','module','require',ts.transpileModule(fs.readFileSync(path.resolve(__dirname,'../estimating-app/lib/'+name+'.ts'),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText)(m.exports,m,n=>n.startsWith('.')?load(n.replace(/^\.\//,'')):require('../estimating-app/node_modules/'+n));return cache[name]=m.exports;}
async function sample(count=2){const pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica);for(let n=1;n<=count;n++){const p=pdf.addPage([612,792]);p.drawText('JGC TEST DRAWING PAGE '+n,{x:70,y:700,size:18,font});p.drawLine({start:{x:70,y:600},end:{x:370,y:600},thickness:2,color:rgb(0,0,0)});if(n===2){p.setCropBox(30,40,540,700);p.setRotation(degrees(90));}}return Buffer.from(await pdf.save());}
function state(){const s=load('estimator-data').createDefaultState();s.clients=[];s.quotes=[];s.priceBook=[];s.jobs=[{id:'job',jobNumber:'26999',quoteId:'',clientId:'',project:'Drawing review',status:'Active',portalJobId:'portal-job',acceptedRevenue:0,originalCostBudget:0,approvedRevenueChanges:0,approvedCostChanges:0,estimateToComplete:0,acceptedAt:'2026-10-01',costs:[],notes:''}];return s;}
async function setup(page,store){await page.route('**/api/**',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({state:state(),jobs:[],actuals:[],rows:[],saved:true})}));await page.route('https://drawings.example.test/**',async r=>{const req=r.request(),u=new URL(req.url());if(u.pathname.startsWith('/storage/')){if(req.method()==='POST'){store.uploaded=true;return r.fulfill({status:200,contentType:'application/json',body:'{"Key":"ok"}'});}return r.fulfill({status:200,contentType:'application/pdf',body:store.bytes});}if(u.pathname.endsWith('/job_drawings')){if(req.method()==='GET')return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify([store.row])});if(req.method()==='PATCH'){const v=req.postDataJSON();if(u.searchParams.get('revision')!=='eq.'+store.row.revision)return r.fulfill({status:200,contentType:'application/json',body:'null'});store.row={...store.row,...v,updated_at:new Date().toISOString()};store.saves++;return r.fulfill({status:200,contentType:'application/json',body:JSON.stringify(store.row)});}if(req.method()==='POST'){const v=req.postDataJSON();store.row={...store.row,...v,object_path:v.id+'/original.pdf'};return r.fulfill({status:201,contentType:'application/json',body:JSON.stringify(store.row)});}}return r.fulfill({status:404,body:'{}'});});await page.goto('/estimating/index.html?dev=1&view=jobs&job=26999');await expect(page.locator('.job-detail-page')).toContainText('26999');await page.evaluate(()=>{window.__drawingBaselineWidth=document.documentElement.scrollWidth;window.createJgcSupabaseClient=()=>window.supabase.createClient('https://drawings.example.test','public-test-key',{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});});await page.getByRole('tab',{name:'Drawings',exact:true}).click();await expect(page.getByLabel('Select drawing').locator('option')).toHaveCount(2);await page.getByLabel('Select drawing').selectOption(store.row.id);await expect(page.locator('.drawing-overlay')).toBeVisible();expect(await page.locator('.drawing-sheet canvas').evaluate(c=>c.width)).toBeGreaterThan(0);}
async function store(){return{bytes:await sample(),saves:0,row:{id:'aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa',job_id:'job',title:'Architectural drawing',file_name:'original.pdf',object_path:'aaaaaaaa-aaaa-4aaa-aaaa-aaaaaaaaaaaa/original.pdf',revision:1,content:load('drawing-model').emptyDrawing(),created_at:'2026-10-01',updated_at:'2026-10-01'}};}
async function drag(page,x=70,y=90,dx=130,dy=0){if(await page.getByRole('button',{name:'Set scale',exact:true}).count()&&await page.getByRole('button',{name:'Set scale',exact:true}).getAttribute('aria-pressed')==='true'){await distance(page,x,y,dx,dy);return;}await page.locator('.drawing-overlay').evaluate(svg=>scrollTo(0,scrollY+svg.getBoundingClientRect().top-240));const b=await page.locator('.drawing-overlay').boundingBox();await page.mouse.move(b.x+x,b.y+y);await page.mouse.down();await page.mouse.move(b.x+x+dx,b.y+y+dy,{steps:5});await page.mouse.up();}
async function distance(page,x=70,y=150,dx=130,dy=0){await page.locator('.drawing-overlay').evaluate(svg=>scrollTo(0,scrollY+svg.getBoundingClientRect().top-240));const b=await page.locator('.drawing-overlay').boundingBox();await page.mouse.click(b.x+x,b.y+y);await page.mouse.move(b.x+x+dx,b.y+y+dy);await page.mouse.click(b.x+x+dx,b.y+y+dy);}
async function text(page,value='As-built: conduit relocated'){await page.getByRole('button',{name:'Edit',exact:true}).click();await page.getByRole('button',{name:'Text',exact:true}).click();await page.locator('.drawing-overlay').evaluate(svg=>scrollTo(0,scrollY+svg.getBoundingClientRect().top-240));const b=await page.locator('.drawing-overlay').boundingBox();await page.mouse.click(b.x+100,b.y+120);await page.getByLabel('Edit drawing comment',{exact:true}).fill(value);}
async function pdfTexts(bytes){const lib=await import(require('node:url').pathToFileURL(path.resolve(__dirname,'../estimating-app/node_modules/pdfjs-dist/legacy/build/pdf.mjs')).href),task=lib.getDocument({data:new Uint8Array(bytes),disableWorker:true}),pdf=await task.promise,text=[];for(let n=1;n<=pdf.numPages;n++){const p=await pdf.getPage(n),content=await p.getTextContent();text.push(content.items.map(i=>i.str).join(' '));}await task.destroy();return text;}

test('replacing scale preserves legacy measurement values and rejects invalid calibrations',()=>{
 const m=load('drawing-model'),previous=m.calibrate([{x:0,y:0},{x:100,y:0}],10,'ft-in'),next=m.calibrate([{x:0,y:0},{x:100,y:0}],6096,'mm');next.displayUnit='ft-in';
 const mark={id:'legacy',kind:'distance',page:1,points:[{x:0,y:0},{x:100,y:0}],color:'#d62828',text:'',author:'Test',createdAt:'2026-10-02T12:00:00Z',layer:'Review'},other={...mark,id:'other',page:2};
 const content={version:1,marks:[mark,other],scales:{'1':previous,'2':previous}},replaced=m.replacePageScale(content,1,next);
 expect(replaced.scales['1'].reference).toEqual(next.reference);expect(m.measurement(replaced.marks[0],next)).toBe('10 ft 0 in');expect(m.measurement({...mark,calibration:{unit:'mm',unitsPerPoint:60.96}},next)).toBe('20 ft 0 in');
 expect(replaced.marks[1]).toBe(other);expect(content.marks[0].calibration).toBeUndefined();expect(m.validateContent(JSON.parse(JSON.stringify(replaced)))).toEqual(replaced);
 for(const unitsPerPoint of [0,-1,Infinity])expect(()=>m.validateContent({...replaced,marks:[{...replaced.marks[0],calibration:{unit:'ft',unitsPerPoint}}]})).toThrow('calibration');
});
test('batch page reorder preserves source order, handles end drops and ignores selected targets',()=>{
 const {reorderDrawingPages:move}=load('drawing-model'),order=[1,2,3,4,5,6,7];
 expect(move(order,[5,1,3,4],null)).toEqual([2,6,7,1,3,4,5]);expect(move(order,[3,4,5],1)).toEqual([3,4,5,1,2,6,7]);expect(move(order,[1,3],6,true)).toEqual([2,4,5,6,1,3,7]);
 expect(move(order,[2,3],3)).toEqual(order);expect(move(order,order,null)).toEqual(order);expect(order).toEqual([1,2,3,4,5,6,7]);
});

test('scale replacement shows one reference and preserves measurements through shared save and export',async({page},info)=>{
 const s=await store();await setup(page,s);await page.getByRole('button',{name:'Measure',exact:true}).click();await distance(page,70,90,130);await page.getByLabel('Known length',{exact:true}).fill('10');await page.getByRole('button',{name:'Apply page scale'}).click();await distance(page,70,150,130);await expect.poll(()=>s.row.content.marks.length).toBe(1);
 await page.getByRole('button',{name:'Replace scale',exact:true}).click();await expect(page.locator('.drawing-scale-reference')).toHaveCount(0);await distance(page,70,250,130);await expect(page.locator('.drawing-scale-reference')).toHaveCount(1);await expect(page.locator('.drawing-scale-reference')).toContainText('enter the known length');await page.getByLabel('Known length',{exact:true}).fill('20');await page.getByRole('button',{name:'Apply page scale'}).click();
 await expect(page.locator('.drawing-scale-reference')).toHaveCount(1);await expect(page.locator('.drawing-scale-reference')).toContainText('20 ft 0 in');await expect(page.locator('.drawing-dimension-label')).toHaveText(['10 ft 0 in']);await distance(page,70,330,130);await expect.poll(()=>s.row.content.marks.length).toBe(2);await expect(page.locator('.drawing-dimension-label')).toHaveText(['10 ft 0 in','20 ft 0 in']);
 const saved=JSON.stringify(s.row.content);await page.getByRole('button',{name:'Replace scale',exact:true}).click();await distance(page,100,200,130);await page.getByRole('button',{name:'Cancel scale replacement',exact:true}).click();expect(JSON.stringify(s.row.content)).toBe(saved);await expect(page.locator('.drawing-scale-reference')).toHaveCount(1);
 await page.getByRole('button',{name:'Refresh drawings',exact:true}).click();await expect(page.locator('.drawing-scale-reference')).toHaveCount(1);await expect(page.locator('.drawing-dimension-label')).toHaveText(['10 ft 0 in','20 ft 0 in']);
 const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Download marked PDF',exact:true}).click();await(await pending).saveAs(info.outputPath('different-detail-scales.pdf'));const exported=await pdfTexts(fs.readFileSync(info.outputPath('different-detail-scales.pdf')));expect(exported[0]).toContain('10 ft 0 in');expect(exported[0]).toContain('20 ft 0 in');await page.locator('.drawing-workspace').screenshot({path:info.outputPath('replaced-scale.png')});
});

