 await dialog.getByLabel('Select multiple', {exact:true}).check();await dialog.getByRole('button',{name:'Page 3',exact:true}).click();await expect(dialog.getByRole('button',{name:'Page 1',exact:true})).toHaveAttribute('aria-pressed','true');await expect(dialog.getByRole('button',{name:'Page 3',exact:true})).toHaveAttribute('aria-pressed','true');
