 await dialog.getByRole('button',{name:'Close organizer',exact:true}).click();await expect(page.getByLabel('Page number',{exact:true})).toHaveValue('4');await expect(page.locator('.drawing-mark text')).toContainText('Markup remains');await page.getByRole('button',{name:'Refresh drawings',exact:true}).click();expect(s.row.content.pageOrder).toEqual([2,6,7,1,3,4,5]);
