 const s=await store(),original=Buffer.from(s.bytes);s.row.content.pageOrder=[2,1];await setup(page,s);await text(page,'Only this second source sheet is reviewed');await expect.poll(()=>s.row.content.marks.length).toBe(1);const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Download this page',exact:true}).click();const file=await pending;expect(file.suggestedFilename()).toContain('Page 1');await file.saveAs(info.outputPath('one-reviewed-page.pdf'));
 const bytes=fs.readFileSync(info.outputPath('one-reviewed-page.pdf')),exported=await PDFDocument.load(bytes),source=await PDFDocument.load(original);expect(exported.getPageCount()).toBe(1);expect(exported.getPage(0).getCropBox()).toEqual(source.getPage(1).getCropBox());expect(exported.getPage(0).getRotation()).toEqual(source.getPage(1).getRotation());expect(exported.getPage(0).node.Annots().size()).toBe(1);
