test('metric calibration converts distances and areas without changing the saved reference',()=>{
 const m=load('drawing-model'),points=[{x:0,y:0},{x:100,y:0}],scale=m.calibrate(points,3048,'mm');
 const distance={kind:'distance',points},area={kind:'area',points:[...points,{x:100,y:100},{x:0,y:100}]};
 for(const [unit,length,surface] of [['ft','10.00 ft','100.00 sq ft'],['ft-in','10 ft 0 in','100.00 sq ft'],['in','120.00 in','14400.00 sq in'],['yd','3.33 yd','11.11 sq yd'],['m','3.048 m','9.29 sq m'],['cm','304.80 cm','92903.04 sq cm'],['mm','3048.00 mm','9290304.00 sq mm']]){
  expect(m.measurement(distance,{...scale,displayUnit:unit})).toBe(length);expect(m.measurement(area,{...scale,displayUnit:unit})).toBe(surface);
 }
 expect(scale.unit).toBe('mm');expect(scale.knownLength).toBe(3048);expect(scale.reference).toEqual(points);
 expect(m.scaleReferenceLabel({...scale,displayUnit:'ft-in'})).toBe('Scale reference - 3048.00 mm');
});

