test('organizer desktop drag scrolls with wheel and at both edges without losing selected pages',async({page})=>{
 await page.setViewportSize({width:1100,height:850});const s=await store();s.bytes=await sample(24);await setup(page,s);await page.getByRole('button',{name:'Organize pages',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Organize pages',exact:true}),scroll=dialog.locator('.drawing-organizer-scroll');await dialog.getByRole('button',{name:'Page 2',exact:true}).click({modifiers:['Control']});const card=dialog.locator('[data-source-page="1"]'),b=await card.boundingBox(),box=await scroll.boundingBox();await page.mouse.move(b.x+b.width/2,b.y+35);await page.mouse.down();await page.mouse.move(b.x+b.width/2+15,b.y+50,{steps:5});await page.mouse.move(box.x+box.width/2,box.y+box.height/2,{steps:5});const before=await scroll.evaluate(el=>el.scrollTop);await page.mouse.wheel(0,180);await expect.poll(()=>scroll.evaluate(el=>el.scrollTop)).toBeGreaterThan(before);await expect(dialog.locator('.drawing-page-cards>div.selected')).toHaveCount(2);await page.mouse.move(box.x+box.width/2,box.y+box.height-10,{steps:5});const middle=await scroll.evaluate(el=>el.scrollTop);await expect.poll(()=>scroll.evaluate(el=>el.scrollTop)).toBeGreaterThan(middle+50);await page.mouse.move(box.x+box.width/2,box.y+8,{steps:5});const lower=await scroll.evaluate(el=>el.scrollTop);await expect.poll(()=>scroll.evaluate(el=>el.scrollTop)).toBeLessThan(lower);await page.keyboard.press('Escape');await page.mouse.up();expect(s.saves).toBe(0);
});

test.describe('organizer phone scrolling',()=>{test.use({hasTouch:true,viewport:{width:390,height:844}});
 test('a held selection and second finger scroll reliably, then moves at a scrolled destination',async({page,browserName},info)=>{
  const s=await store();s.bytes=await sample(24);s.row.content.scales['1']=load('drawing-model').calibrate([{x:0,y:0},{x:100,y:0}],10,'ft-in');const scale=JSON.stringify(s.row.content.scales);await setup(page,s);await page.getByRole('button',{name:'Organize pages',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Organize pages',exact:true}),scroll=dialog.locator('.drawing-organizer-scroll');await dialog.getByLabel('Select multiple',{exact:true}).check();await dialog.getByRole('button',{name:'Page 2',exact:true}).tap();const b=await scroll.boundingBox(),first={x:b.x+65,y:b.y+40},second={x:b.x+b.width-60,y:b.y+Math.min(b.height-25,200)};
  if(browserName==='chromium'){const cdp=await page.context().newCDPSession(page),touch=async(type,pts)=>cdp.send('Input.dispatchTouchEvent',{type,touchPoints:pts.map((p,i)=>({...p,id:i+1}))});await touch('touchStart',[first]);await touch('touchStart',[first,second]);for(let n=1;n<=6;n++)await touch('touchMove',[first,{x:second.x,y:second.y-n*20}]);await touch('touchEnd',[]);}else await scroll.evaluate((el,{first,second})=>{const dispatch=(type,points)=>{const event=new Event(type,{bubbles:true,cancelable:true});Object.assign(event,{touches:points.map((p,i)=>({...p,identifier:i+1,clientX:p.x,clientY:p.y})),changedTouches:[]});el.dispatchEvent(event);};dispatch('touchstart',[first]);dispatch('touchstart',[first,second]);dispatch('touchmove',[first,{x:second.x,y:second.y-120}]);dispatch('touchend',[]);},{first,second});
  await expect.poll(()=>scroll.evaluate(el=>el.scrollTop)).toBeGreaterThan(60);await expect(dialog.locator('.drawing-page-cards>div.selected')).toHaveCount(2);expect(s.saves).toBe(0);await dialog.getByRole('button',{name:'Move selected pages',exact:true}).tap();await dialog.getByRole('button',{name:'Move selected pages after page 20',exact:true}).scrollIntoViewIfNeeded();await dialog.getByRole('button',{name:'Move selected pages after page 20',exact:true}).tap();await expect.poll(()=>s.row.content.pageOrder?.join(',')).toBe([...Array.from({length:18},(_,i)=>i+3),1,2,21,22,23,24].join(','));expect(JSON.stringify(s.row.content.scales)).toBe(scale);await dialog.screenshot({path:info.outputPath('scrolled-organizer.png')});
 });
});

